Here's a Python implementation of BFS to find a path between two nodes in an unweighted graph:

```python
from collections import deque

class Graph:
    def __init__(self, graph_dict=None):
        if graph_dict is None:
            graph_dict = {}
        self.graph_dict = graph_dict

    def add_vertex(self, vertex):
        if vertex not in self.graph_dict:
            self.graph_dict[vertex] = []

    def add_edge(self, vertex1, vertex2):
        if vertex1 in self.graph_dict:
            self.graph_dict[vertex1].append(vertex2)
        else:
            self.graph_dict[vertex1] = [vertex2]
        if vertex2 in self.graph_dict:
            self.graph_dict[vertex2].append(vertex1)
        else:
            self.graph_dict[vertex2] = [vertex1]

    def bfs(self, start_vertex, end_vertex):
        if start_vertex not in self.graph_dict or end_vertex not in self.graph_dict:
            return None

        visited = set()
        queue = deque([(start_vertex, [start_vertex])])

        while queue:
            current_vertex, path = queue.popleft()
            if current_vertex == end_vertex:
                return path

            for neighbor in self.graph_dict[current_vertex]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))

        return None

