### 1. Depth-First Search (DFS)
DFS is a simple algorithm that works well for small graphs. It explores as far as possible along each branch before backtracking.

```python
class Graph:
    def __init__(self, edges):
        self.vertices = {}
        for edge in edges:
            u, v = edge
            if u not in self.vertices:
                self.vertices[u] = []
            if v not in self.vertices:
                self.vertices[v] = []
            self.vertices[u].append(v)
            self.vertices[v].append(u)

    def dfs(self, start, goal, visited=None):
        if visited is None:
            visited = set()
        if start == goal:
            return [start]
        visited.add(start)
        path = []
        for neighbor in self.vertices[start]:
            if neighbor not in visited:
                new_path = self.dfs(neighbor, goal, visited)
                if new_path:
                    path.append(start)
                    path.extend(new_path)
                    break
        return path

