import math

class Node:
    def __init__(self, state, parent=None, action=None, path_cost=0):
        self.state = state
        self.parent = parent
        self.action = action
        self.path_cost = path_cost

    def expand(self, graph):
        children = []
        for state in graph.get_successors(self.state):
            children.append(Node(state, self, state, self.path_cost + 1))
        return children

    def path_trace(self):
        node, path_back = self, []
        while node:
            path_back.append(node)
            node = node.parent
        return list(reversed(path_back))

    def heuristic(self, goal):
        return self.get_manhattan_distance(goal)

    def get_manhattan_distance(self, goal):
        if not isinstance(goal, tuple):
            raise ValueError("Goal must be a tuple (x, y)")
        return abs(self.state[0] - goal[0]) + abs(self.state[1] - goal[1])

    def get_cost(self, graph):
        return self.path_cost

def a_star_search(graph, start, goal):
    closed_nodes = set()
    open_nodes = [Node(start)]
    while open_nodes:
        current_node = min(open_nodes, key=lambda node: node.heuristic(goal))
        if current_node.state == goal:
            return current_node.path_trace()
        open_nodes.remove(current_node)
        closed_nodes.add(current_node.state)
