    def __init__(self, graph_dict=None, directed=True):
        """
        Initializes the graph object. If no dictionary is provided,
        an empty dictionary is used.
        """
        if graph_dict is None:
            graph_dict = {}
        self.graph_dict = graph_dict
        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        """
        Make a digraph into an undirected graph by adding symmetric edges.
        """
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.add_edge(b, a, dist)

    def add_vertex(self, vertex):
        """
        Add a vertex to the graph.
        """
        if vertex not in self.graph_dict:
            self.graph_dict[vertex] = {}

    def add_edge(self, start, end, distance=1):
        """
        Add an edge to the graph.
        """
        if start not in self.graph_dict:
            self.add_vertex(start)
        if end not in self.graph_dict:
            self.add_vertex(end)
        self.graph_dict[start][end] = distance
        if not self.directed:
            self.graph_dict[end][start] = distance

    def get_neighbors(self, vertex):
        """
        Get all neighbors of a vertex.
        """
        return list(self.graph_dict[vertex].keys())

    def BFS(self, start, end, path=None, cost=None):
        """
        Perform a Breadth-First Search (BFS) to find a path between two vertices.
        """
        if path is None:
            path = [start]
        if cost is None:
            cost = 0
        if start == end:
            return [path, cost]

        shortest_path = None
        for (vertex, distance) in self.graph_dict[start].items():
            if vertex not in path:
                new_path = self.BFS(vertex, end, path + [vertex], cost + distance)
                if new_path is not None:
                    if shortest_path is None or len(new_path[0]) < len(shortest_path[0]):
                        shortest_path = new_path

        return shortest_path


