### BFS Implementation

BFS works by exploring all the neighbors of a node before moving to the next level of nodes. It's particularly useful for finding the shortest path in unweighted graphs or grids.

```python
from collections import deque

def bfs(grid, start, end):
    if not grid or not grid[0]:
        return None

    # Directions for moving up, down, left, right
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Queue for BFS and a dictionary to keep track of visited nodes
    queue = deque([start])
    visited = {start: None}

    while queue:
        current = queue.popleft()
        if current == end:
            return build_path(visited, start, end)

        for dx, dy in directions:
            next_cell = (current[0] + dx, current[1] + dy)
            if is_valid(grid, next_cell) and next_cell not in visited:
                visited[next_cell] = current
                queue.append(next_cell)

    return None

def is_valid(grid, cell):
    m, n = len(grid), len(grid[0])
    return 0 <= cell[0] < m and 0 <= cell[1] < n and grid[cell[0]][cell[1]] != 1

def build_path(visited, start, end):
    path = []
    while end in visited:
        path.append(end)
        end = visited[end]
    path.append(start)
    return list(reversed(path))

